"use client";

import { forwardRef } from "react";
import { noiseDefaults, type NoiseSpecProps } from "../generated/noise.types";
import { cx } from "../utils/cx";
import { motionVars } from "../utils/motion";
import type { PatternDivProps } from "../utils/pattern";

export interface NoiseProps extends NoiseSpecProps, Omit<PatternDivProps, keyof NoiseSpecProps> {}

/** A fine grain laid over its parent. Still unless you ask. Decoration: hidden from assistive technology, ignores the pointer. */
export const Noise = forwardRef<HTMLDivElement, NoiseProps>(function Noise(
  {
    opacity = noiseDefaults.opacity,
    size = noiseDefaults.size,
    animated = noiseDefaults.animated,
    isStill = noiseDefaults.isStill,
    className,
    style,
    ...rest
  },
  ref,
) {
  return (
    <div
      {...rest}
      ref={ref}
      aria-hidden="true"
      data-animated={animated || undefined}
      data-rdm-still={isStill || undefined}
      className={cx("rdm-pattern rdm-noise", className)}
      style={{ ...style, ...motionVars({ "--rdm-op": opacity, "--rdm-p": `${size}px` }) }}
    />
  );
});

// Generated by rdloom codegen from specs/noise.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

/** A fine static grain laid over a surface with CSS, still by default. */
export interface NoiseSpecProps {
  /**
   * Strength of the grain, from 0 to 1.
   * @default 0.08
   */
  opacity?: number;
  /**
   * Size of one grain tile in pixels.
   * @default 160
   */
  size?: number;
  /**
   * Shifts the grain slowly, about once a second. Off by default.
   * @default false
   */
  animated?: boolean;
  /**
   * Stops the shift. Moving content should be stoppable.
   * @default false
   */
  isStill?: boolean;
}

export const noiseDefaults = {
  opacity: 0.08,
  size: 160,
  animated: false,
  isStill: false,
} as const;

export const noiseMeta = {
  "name": "Noise",
  "version": "0.1.0",
  "status": "experimental",
  "role": "presentation"
} as const;
